@Override // ru.jecklandin.stickman.editor2.BaseActivity, androidx.fragment.app.FragmentActivity, androidx.activity.ComponentActivity, androidx.core.app.ComponentActivity, android.app.Activity
public void onCreate(@Nullable Bundle savedInstanceState) {
    super.onCreate(savedInstanceState);
    setContentView(R.layout.preview_activity_container);
    this.mMotionGraph = (FullscreenHint) findViewById(R.id.fs_hint);
    hideMotionGraphUi();
    this.mBoneToggle = (Button) findViewById(R.id.preview_bone_toggle);
    hideBoneToggleUi();
    if (!StickmanApp.sInstance.mInitialized.isReady()) {
        finish();
        Log.d(TAG, "App is not ready yet");
        return;
    }
    if (getIntent().getBooleanExtra(EXTRA_VARSPEEDS, false)) {
        hideBoneToggleUi();
        FullscreenHint fullscreenHint = this.mMotionGraph;
        if (fullscreenHint != null) {
            fullscreenHint.hide();
        }
        showVarSpeed(this.mCartoonStage);
        return;
    }
    boolean z = AdsUtils.hideAds() || getIntent().getBooleanExtra(EXTRA_NOADS, false) || this.mAutoExit;
    this.mTryInterstitial = AdsUtils.shouldLoadInterstitial();
    showSimplePreview(this.mCartoonStage, !AdsUtils.PURE_ADMOB || z);
    if (AdsUtils.PURE_ADMOB) {
        InterstitialCallback.initAdmob(this.mTryInterstitial);
    } else {
        InterstitialCallback.initAppodeal(this);
    }
}
